#!/usr/bin/env python3
"""patch_kind_vocabulary.py -- wire the dressing kit into the suite, and test
the "keep in sync" comment that three kinds had already drifted out of.

WHAT WAS ACTUALLY BROKEN.

`core.skins.KNOWN_KINDS` and `bpylayer.materials.ROUGHNESS` are one material
vocabulary written in two places. Each carries a comment telling the reader to
keep them in sync, and nothing enforced it. Sweeping every kind named by all 53
species genomes against both lists turned up three orphans:

  tar          declared by the `roof` species since it shipped. In NEITHER
               list, so every roof took `make_material`'s 0.6 default
               roughness and `find_pack` could never resolve a skin pack for
               it. Nothing failed. It has simply been quietly wrong for the
               life of the species, and the only reason it surfaced now is
               that something finally looked.
  gravel       Layer 3 dressing, same drift.
  vegetation   Layer 3 dressing, same drift.

All three go into both lists, and `tests/test_kind_vocabulary.py` holds them
there -- it asserts the two lists agree AND that every kind any genome names
appears in them, failing with the species that names the orphan rather than a
bare "something is missing".

That test reads `materials.py` with `ast` instead of importing it. The module
imports bpy at scope, and the zoo suite runs without Blender (`test_skins.py`
opens by saying so), so an importing test would be unrunnable in exactly the
environment that needs it -- which is why this check never got written.

ALSO: `test_genome.test_all_species_load_and_validate` IS RED ON YOUR MACHINE
RIGHT NOW, and was before any of this session's patches. It asserts exact
equality between the declared species sets and the genome folder, and the four
Layer 3 species were never declared:

    PROP_SPECIES | ARCH_SPECIES  ->  49
    genome/species/*.json        ->  53

They are added as `DRESSING_SPECIES`, deliberately a third category: neither
individually-modelled props with their own silhouettes, nor Deli Counter
slot-driven modules. Nothing places them by slot and nothing places them by
name -- they are scattered, and the scatter is the unit.

VERSION 0.36.0 -> 0.37.0, with a CHANGELOG entry covering this and the two
shape patches that preceded it (neither had one).

VERIFIED BEFORE SHIPPING, by reverting each piece in turn and confirming the
new tests go red -- a test that cannot fail is not a test:

    original skins.py back      -> 4 failed, 4 passed
    original materials.py back  -> 2 failed, 6 passed
    original test_genome.py back-> 1 failed, 1 passed
    everything applied          -> 10 passed

    python patch_kind_vocabulary.py --check
    python patch_kind_vocabulary.py --selftest
    python patch_kind_vocabulary.py
    python patch_kind_vocabulary.py --revert
"""
