def repo_root(start=None):
    d = os.path.abspath(start or os.path.dirname(os.path.abspath(__file__)))
    for _ in range(8):
        if (os.path.isdir(os.path.join(d, "zoo", "zoo_keeper"))
                and os.path.isdir(os.path.join(d, "tools"))):
            return d
        nd = os.path.dirname(d)
        if nd == d:
            break
        d = nd
    return None


def sha(b):
    return hashlib.sha256(b).hexdigest()


def rd(p):
    with open(p, "rb") as fh:
        return fh.read()


def wr(p, b):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "wb") as fh:
        fh.write(b)


def plan(root):
    rows, ok = [], True
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        exists = os.path.isfile(p)
        if d["kind"] == "new":
            if exists and sha(rd(p)) == d["post_sha"]:
                rows.append((rel, "already-current", True))
            elif exists:
                rows.append((rel, "EXISTS AND DIFFERS - refusing", False))
                ok = False
            else:
                rows.append((rel, f"create {d['post_bytes']} B", True))
            continue
        if not exists:
            rows.append((rel, "MISSING - refusing", False))
            ok = False
            continue
        cur = sha(rd(p))
        if cur == d["post_sha"]:
            rows.append((rel, "already-current", True))
        elif cur == d["pre_sha"]:
            rows.append((rel, f"replace {d['pre_bytes']} -> {d['post_bytes']} B",
                         True))
        else:
            rows.append((rel, f"DRIFT sha {cur[:12]} != {d['pre_sha'][:12]}",
                         False))
            ok = False
    return ok, rows


def show(rows):
    w = max(len(r[0]) for r in rows)
    for rel, msg, good in rows:
        print(f"  {'ok ' if good else 'STOP'}  {rel:<{w}}  {msg}")


def apply(root):
    ok, rows = plan(root)
    show(rows)
    if not ok:
        print("\nREFUSING: nothing written. Resolve the lines marked STOP.")
        return 1
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        if os.path.isfile(p):
            cur = rd(p)
            if sha(cur) == d["post_sha"]:
                continue
            side = p + SIDECAR
            if not os.path.exists(side):
                wr(side, cur)
        wr(p, base64.b64decode(d["b64"]))
        assert sha(rd(p)) == d["post_sha"], rel
        n += 1
    print(f"\nWROTE {n} file(s). Sidecars: *{SIDECAR}")
    print("Next:")
    print("  cd zoo")
    print("  python -m pytest tests -q")
    print("Expect test_kind_vocabulary (8 tests) and test_genome to be green.")
    print("test_genome was RED before this patch, so a green run there is the")
    print("thing to look for, not the absence of new failures.")
    return 0


def revert(root):
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        side = p + SIDECAR
        if os.path.exists(side):
            wr(p, rd(side))
            os.remove(side)
            print(f"  reverted {rel}")
            n += 1
        elif d["kind"] == "new" and os.path.isfile(p):
            if sha(rd(p)) == d["post_sha"]:
                os.remove(p)
                print(f"  removed  {rel} (this patch created it)")
                n += 1
            else:
                print(f"  KEPT     {rel} (modified since; not ours to delete)")
    print(f"reverted {n} file(s)")
    return 0


def selftest():
    bad = 0

    def fail(msg):
        nonlocal bad
        print(f"  FAIL  {msg}")
        bad += 1

    print("patch_kind_vocabulary selftest")

    for rel, d in PAYLOAD.items():
        b = base64.b64decode(d["b64"])
        if sha(b) != d["post_sha"] or len(b) != d["post_bytes"]:
            fail(f"payload {rel} does not match its recorded hash/size")
    print(f"  ok    {len(PAYLOAD)} payloads decode to their recorded hashes")

    import ast

    skins_src = base64.b64decode(
        PAYLOAD["zoo/zoo_keeper/core/skins.py"]["b64"]).decode("utf-8")
    mats_src = base64.b64decode(
        PAYLOAD["zoo/zoo_keeper/bpylayer/materials.py"]["b64"]).decode("utf-8")

    # Read both vocabularies out of the PAYLOADS, not off disk, so this
    # verifies what is about to be written rather than what is already there.
    def _literal(src, name):
        r"""Pull a module-level literal out by parsing, never by regex.

        The first draft of this used `re.search(r"KNOWN_KINDS = (\(.*?\))")`
        and blew up: the tuple contains an inline comment reading
        "(docs/SURFACE_DRESSING.md)", so the non-greedy match closed on that
        parenthesis. Parsing has no such failure mode.

        (The docstring is raw so the backslashes above are literal text and
        not an invalid escape sequence -- which is what the first fix for the
        first bug then warned about on every run.)
        """
        for node in ast.parse(src).body:
            if isinstance(node, ast.Assign) and any(
                    isinstance(t, ast.Name) and t.id == name
                    for t in node.targets):
                v = node.value
                if isinstance(v, ast.Dict):
                    return {ast.literal_eval(k) for k in v.keys}
                return set(ast.literal_eval(v))
        return None

    known = _literal(skins_src, "KNOWN_KINDS")
    rough = _literal(mats_src, "ROUGHNESS")
    if known is None:
        fail("could not parse KNOWN_KINDS out of the skins.py payload")
        known = set()
    if rough is None:
        fail("could not parse ROUGHNESS out of the materials.py payload")
    elif known != rough:
        fail(f"the payloads themselves disagree: only-KNOWN={sorted(known - rough)} "
             f"only-ROUGHNESS={sorted(rough - known)}")
    else:
        print(f"  ok    both payloads carry the same {len(known)} kinds")

    for kind in ("tar", "gravel", "vegetation"):
        if kind not in known:
            fail(f"{kind} missing from the KNOWN_KINDS payload")
    print("  ok    tar, gravel and vegetation are in the new vocabulary")

    # FALSIFICATION: the comparison above must be capable of failing. Drop one
    # kind and it has to notice; if it does not, the whole check is theatre.
    if known == (rough - {"tar"}):
        fail("removing a kind did not change the comparison")
    else:
        print("  ok    removing one kind is detected")

    tg = base64.b64decode(
        PAYLOAD["zoo/tests/test_genome.py"]["b64"]).decode("utf-8")
    for name in ("pebble", "rubble_frag", "weed_tuft", "litter_scrap"):
        if name not in tg:
            fail(f"test_genome payload does not declare {name}")
    if "PROP_SPECIES | ARCH_SPECIES | DRESSING_SPECIES" not in tg:
        fail("test_genome payload does not fold DRESSING_SPECIES into the "
             "equality assertion, so adding the set changes nothing")
    print("  ok    test_genome payload declares and asserts DRESSING_SPECIES")

    ver = base64.b64decode(PAYLOAD["zoo/VERSION"]["b64"]).decode("utf-8")
    if ver.strip() != "Zoo 0.37.0":
        fail(f"VERSION payload is {ver.strip()!r}")
    ch = base64.b64decode(
        PAYLOAD["zoo/CHANGELOG.md"]["b64"]).decode("utf-8")
    if "## [0.37.0]" not in ch:
        fail("CHANGELOG payload has no 0.37.0 entry")
    if "## [0.36.0]" not in ch:
        fail("CHANGELOG payload lost the previous entries")
    print("  ok    VERSION 0.37.0 and a CHANGELOG entry that keeps 0.36.0")

    ref = base64.b64decode(next(iter(PAYLOAD.values()))["b64"])
    mut = bytearray(ref)
    mut[len(mut) // 2] ^= 0x20
    if sha(bytes(mut)) == sha(ref):
        fail("a mutated payload hashed identically")
    else:
        print("  ok    one flipped byte changes the hash")

    print("SELFTEST", "PASSED" if bad == 0 else f"FAILED ({bad})")
    return 1 if bad else 0


def main(argv):
    if "--selftest" in argv:
        return selftest()
    root = None
    if "--root" in argv:
        root = os.path.abspath(argv[argv.index("--root") + 1])
    root = root or repo_root()
    if not root:
        print("Could not find the gabagool_factory root. Pass --root <path>.")
        return 2
    print(f"repo root: {root}")
    if "--revert" in argv:
        return revert(root)
    ok, rows = plan(root)
    if "--check" in argv:
        show(rows)
        print("\n--check only: nothing written."
              + ("" if ok else "  RESOLVE THE STOP LINES FIRST."))
        return 0 if ok else 1
    return apply(root)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
